<script setup>
import {ref,computed,watch,nextTick,onMounted,onUnmounted} from 'vue';import {Head,Link,usePage,router} from '@inertiajs/vue3';import axios from 'axios';
import {art,message} from '../art';import RecallBalance from '../Components/RecallBalance.vue';import SaveNotice from '../Components/SaveNotice.vue';
import StudyDetails from '../Components/StudyDetails.vue';import StudyDock from '../Components/StudyDock.vue';import StudySheet from '../Components/StudySheet.vue';
import {useStudyDelivery} from '../useStudyDelivery';import {answerKey} from '../studyDelivery';
const props=defineProps({deck:Object,bookmarks:{type:Array,default:()=>[]}}),page=usePage(),data=ref(props.deck),sessionBusy=ref(false),sessionError=ref(''),goalDialog=ref(null),progress=ref(null),help=ref(null),menu=ref(null),showQuestion=ref(false),answerHeading=ref(null),chosenGrade=ref(null);
watch(()=>props.deck,deck=>{data.value=deck;sessionError.value=''});
const q=computed(()=>data.value.question),answered=computed(()=>q.value?.answer!=null),labels=['Again','Hard','Okay','Good','Easy'];
async function goal(){await nextTick();if(data.value.goal_prompt&&!data.value.finished&&!goalDialog.value?.open)goalDialog.value?.showModal();else if(!data.value.goal_prompt)goalDialog.value?.close()}
watch(()=>data.value.goal_prompt,goal);onMounted(goal);
function accept(r){data.value=r.data.deck;if(r.data.achievement)page.props.achievement=r.data.achievement;if(r.data.community)page.props.community=r.data.community}
const delivery=useStudyDelivery('sushi:pending:'+page.props.user.id+':deck:'+data.value.id,'/flashcards/decks/'+data.value.id,accept);
const {pending,status,retry,discard}=delivery,busy=computed(()=>sessionBusy.value||delivery.busy.value||!!pending.value),error=computed(()=>sessionError.value||delivery.error.value);
async function answer(value){if(busy.value||data.value.goal_prompt)return;sessionError.value='';await delivery.send('answer',{question_id:q.value.id,answer:value,token:q.value.token})}
async function rate(confidence){if(busy.value||data.value.goal_prompt)return;sessionError.value='';chosenGrade.value=confidence;await delivery.send('rate',{question_id:q.value.id,confidence,token:q.value.token})}
function exitCheck(){if(busy.value)return;sessionBusy.value=true;router.post('/flashcards/decks/'+data.value.id+'/exit-check',{session_number:data.value.session_number},{onFinish:()=>sessionBusy.value=false})}
function reload(){discard();router.reload()}
async function session(action){if(busy.value)return;sessionBusy.value=true;sessionError.value='';try{accept(await axios.post('/flashcards/decks/'+data.value.id+'/session',{action,session_number:data.value.session_number},{timeout:20000}));goalDialog.value?.close();if(action==='resume')await goal();window.scrollTo({top:0,behavior:'instant'})}catch(e){sessionError.value=message(e)}finally{sessionBusy.value=false}}
function keys(e){const key=answerKey(e);if(!key||busy.value||!q.value||data.value.finished||document.querySelector('dialog[open]'))return;if(answered.value){if(!/^[1-5]$/.test(e.key))return;e.preventDefault();rate(key)}else if(key<=4){e.preventDefault();answer(String.fromCharCode(64+key))}}
watch(()=>q.value?.token,()=>{showQuestion.value=false;chosenGrade.value=null;window.scrollTo({top:0,behavior:'instant'})});
watch(answered,async value=>{if(value){showQuestion.value=false;await nextTick();window.scrollTo({top:0,behavior:'instant'});answerHeading.value?.focus({preventScroll:true})}});
let pulse;onMounted(()=>{window.addEventListener('keydown',keys);pulse=setInterval(()=>{if(!document.hidden&&!data.value.finished)axios.post('/study/active').catch(()=>{})},60000)});onUnmounted(()=>{clearInterval(pulse);window.removeEventListener('keydown',keys)});
</script>
<template><Head :title="data.title"/><div class="study-heading"><div><h1>Memory Maki</h1><p>{{data.total}} {{data.total===1?'card':'cards'}} · {{data.counts[5]}} rated 5</p></div><details ref="menu" class="study-menu"><summary aria-label="Memory Maki menu">•••</summary><div><Link href="/flashcards?new=1">New deck</Link><Link href="/flashcards?decks=1">Saved decks</Link><button @click="menu.open=false;progress.open()">Deck progress</button><button @click="menu.open=false;help.open()">Study help</button><button v-if="!data.finished" :disabled="busy" @click="menu.open=false;session('finish')">Finish session</button></div></details></div>
<progress class="study-progress" :value="data.counts[5]" :max="data.total||1" aria-label="Cards rated 5"/>
<SaveNotice v-if="pending||error" :status="status" :error="error" :pending="pending" :busy="delivery.busy.value" @retry="retry" @reload="reload"/>
<section v-if="data.finished" class="panel session-summary"><img class="portrait" :src="art.memo" alt="Memo Maki"><h2>Session complete</h2><p role="status">Your progress is saved.</p><div class="summary-metrics"><div><strong>{{data.session_reviews}}</strong><span>Reviews</span></div><div><strong>{{data.counts[5]}}/{{data.total}}</strong><span>Rated 5</span></div><div><strong>{{data.accuracy.total?Math.round(data.accuracy.correct/data.accuracy.total*100)+'%':'—'}}</strong><span>Answer accuracy</span></div></div><div class="row"><button class="primary" :disabled="busy" @click="session('resume')">Resume deck</button><Link class="button" href="/flashcards?new=1">New deck</Link><Link href="/">Counter</Link></div><div v-if="data.exit_quiz||data.counts[5]>=data.goal_target" class="summary-next"><Link v-if="data.exit_quiz" class="button" :href="'/memory-checks/'+data.exit_quiz.id">{{data.exit_quiz.finished_at?'Recall results':'Resume recall check'}}</Link><button v-else :disabled="busy" @click="exitCheck">Try {{Math.min(5,data.total)}}-question recall check</button></div></section>
<article v-else-if="q" class="panel focused-question memory-question" :class="{'answer-view':answered}">
<template v-if="answered"><div class="recall-answer" role="status"><p :class="q.correct?'result-correct':'result-incorrect'">{{q.correct?'Correct':'Incorrect'}}</p><small>Correct answer</small><h2 ref="answerHeading" tabindex="-1" class="pre">{{q.key}} · {{q.options[q.key.charCodeAt(0)-65]}}</h2><p v-if="!q.correct" class="your-answer">Your answer: {{q.answer}} · {{q.options[q.answer.charCodeAt(0)-65]}}</p></div><button class="view-question" :aria-expanded="showQuestion" aria-controls="memory-question" @click="showQuestion=!showQuestion">{{showQuestion?'Hide question':'View question'}}</button></template>
<section v-if="!answered||showQuestion" id="memory-question"><div class="card-meta"><span>{{q.subject}}</span><button class="plain" :disabled="busy" :aria-pressed="bookmarks.includes(q.id)" @click="router.post('/bookmarks/'+q.id,{bookmarked:!bookmarks.includes(q.id)},{preserveScroll:true})">{{bookmarks.includes(q.id)?'Saved':'Save question'}}</button></div><h2 class="question-stem pre">{{q.stem}}</h2><div class="options"><button v-for="(option,i) in q.options" :key="i" :disabled="busy||answered||data.goal_prompt" :aria-pressed="q.answer===String.fromCharCode(65+i)" :class="{selected:q.answer===String.fromCharCode(65+i),correct:q.key===String.fromCharCode(65+i),incorrect:q.key&&q.answer===String.fromCharCode(65+i)&&q.answer!==q.key}" @click="answer(String.fromCharCode(65+i))"><strong>{{String.fromCharCode(65+i)}}.</strong><span>{{option}}</span></button></div></section>
<StudyDetails v-if="answered" :key="q.token" :question="q"/>
</article><section v-else class="panel"><p>No question is available in this deck.</p><Link class="button" href="/flashcards?new=1">New deck</Link></section>
<StudyDock v-if="answered&&!data.finished"><h2 class="rating-title">{{busy&&chosenGrade?'Saving grade '+chosenGrade+'…':'Rate your recall'}}</h2><div class="recall-buttons"><button v-for="(label,i) in labels" :key="label" :data-grade="i+1" :aria-label="'Grade '+(i+1)+': '+label" :aria-pressed="chosenGrade===i+1" :disabled="busy||data.goal_prompt" @click="rate(i+1)"><strong>{{i+1}}</strong><span>{{label}}</span></button></div></StudyDock>
<StudySheet ref="progress" title="Deck progress"><h3>{{data.title}}</h3><div class="rating-distribution"><div v-for="(count,i) in data.counts" :key="i"><strong>{{count}}</strong><span>{{i===0?'Unrated':i+' '+labels[i-1]}}</span></div></div><RecallBalance :calibration="data.calibration" :accuracy="data.accuracy"/><p>{{data.reviews}} total ratings · {{data.session_reviews}} this session</p><Link v-if="data.exit_quiz" :href="'/memory-checks/'+data.exit_quiz.id">Recall check</Link></StudySheet>
<StudySheet ref="help" title="Study help"><p>Choose an answer, then open Explanation when you want the rationale. Rate your recall from 1 to 5 to save and continue.</p><p>Lower-rated and unrated cards appear more often. At 80% rated 5, you can finish or keep going. Ratings describe familiarity, separately from answer accuracy.</p><p>Your deck and history stay saved. Retry any failed save before moving on.</p><p>Keyboard: A–D answers; 1–5 rates recall after answering.</p></StudySheet>
<dialog ref="goalDialog" class="tier-dialog compact-goal" aria-labelledby="goal-title" @cancel.prevent="session('continue')"><h2 id="goal-title">80% rated 5</h2><p>{{data.counts[5]}}/{{data.total}} cards rated 5. Continue or finish this session?</p><p v-if="error" class="error" role="alert">{{error}}</p><div class="row"><button :disabled="busy" @click="session('continue')">Keep going</button><button class="primary" :disabled="busy" @click="session('finish')">Finish session</button></div></dialog>
</template>
